//! Status command implementation.
//!
//! The `bivvy status` command shows current setup status.

use std::collections::HashSet;
use std::path::{Path, PathBuf};
use std::time::Duration;

use crate::cli::args::StatusArgs;
use crate::config::load_merged_config;
use crate::environment::resolver::ResolvedEnvironment;
use crate::error::{BivvyError, Result};
use crate::requirements::checker::GapChecker;
use crate::requirements::probe::EnvironmentProbe;
use crate::requirements::registry::RequirementRegistry;
use crate::requirements::status::RequirementStatus;
use crate::state::{ProjectId, StateStore, StepStatus};
use crate::ui::theme::BivvyTheme;
use crate::ui::{format_relative_time, hints, OutputMode, StatusKind, UserInterface};

use super::dispatcher::{Command, CommandResult};

/// The status command implementation.
pub struct StatusCommand {
    project_root: PathBuf,
    args: StatusArgs,
}

impl StatusCommand {
    /// Create a new status command.
    pub fn new(project_root: &Path, args: StatusArgs) -> Self {
        Self {
            project_root: project_root.to_path_buf(),
            args,
        }
    }

    /// Get the project root path.
    pub fn project_root(&self) -> &Path {
        &self.project_root
    }

    /// Get the command arguments.
    pub fn args(&self) -> &StatusArgs {
        &self.args
    }

    /// Resolve the target environment using the priority chain.
    fn resolve_environment(&self, config: &crate::config::BivvyConfig) -> ResolvedEnvironment {
        ResolvedEnvironment::resolve_from_config(self.args.env.as_deref(), &config.settings)
    }
}

impl Command for StatusCommand {
    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
        // Load configuration
        let config = match load_merged_config(&self.project_root) {
            Ok(c) => c,
            Err(BivvyError::ConfigNotFound { .. }) => {
                ui.error("No configuration found. Run 'bivvy init' first.");
                return Ok(CommandResult::failure(2));
            }
            Err(e) => return Err(e),
        };

        // Apply config default_output when no CLI flag was explicitly set
        if ui.output_mode() == OutputMode::Normal {
            ui.set_output_mode(config.settings.default_output.into());
        }

        // Get project identity
        let project_id = ProjectId::from_path(&self.project_root)?;

        // Load state
        let state = StateStore::load(&project_id)?;

        let theme = BivvyTheme::new();

        // Resolve environment
        let resolved_env = self.resolve_environment(&config);

        // Show header: ⛺ AppName — Status
        let app_name = config.app_name.as_deref().unwrap_or("Bivvy Setup");
        ui.message(&format!(
            "\n  {} {} {} {}\n",
            theme.header.apply_to("⛺"),
            theme.highlight.apply_to(app_name),
            theme.dim.apply_to("—"),
            theme.dim.apply_to("Status"),
        ));

        // Show environment info
        ui.message(&format!(
            "  {} {} ({})",
            theme.key.apply_to("Environment:"),
            theme.highlight.apply_to(&resolved_env.name),
            theme.dim.apply_to(resolved_env.source.to_string()),
        ));
        ui.message("");

        // Show last run info with relative time
        if let Some(last_run) = state.last_run_record() {
            ui.message(&format!(
                "  {} {} {} {}",
                theme.key.apply_to("Last run:"),
                theme.dim.apply_to(format_relative_time(last_run.timestamp)),
                theme.dim.apply_to("·"),
                theme
                    .dim
                    .apply_to(format!("{} workflow", last_run.workflow)),
            ));
            ui.message("");
        }

        // Show step status
        ui.message(&format!("  {}", theme.key.apply_to("Steps:")));

        let step_names: Vec<&String> = if let Some(ref step_name) = self.args.step {
            if config.steps.contains_key(step_name) {
                vec![step_name]
            } else {
                ui.error(&format!("Unknown step: {}", step_name));
                return Ok(CommandResult::failure(1));
            }
        } else {
            config.steps.keys().collect()
        };

        for step_name in &step_names {
            // Check if step is skipped by only_environments
            let step_config = config.steps.get(*step_name);
            let skipped = step_config
                .map(|s| {
                    !s.only_environments.is_empty()
                        && !s.only_environments.iter().any(|e| e == &resolved_env.name)
                })
                .unwrap_or(false);

            if skipped {
                ui.message(&format!(
                    "    {} {:<20} {}",
                    theme.dim.apply_to("⊘"),
                    step_name,
                    theme
                        .dim
                        .apply_to(format!("(skipped in {})", resolved_env.name)),
                ));
                continue;
            }

            let step_state = state.get_step(step_name);
            let status = step_state.map(|s| s.status).unwrap_or(StepStatus::NeverRun);
            let kind = StatusKind::from(status);

            // Build the right-side info (duration or relative time)
            let right_side = step_state
                .and_then(|s| {
                    if status == StepStatus::NeverRun {
                        return None;
                    }
                    // Show duration if available, otherwise relative timestamp
                    if let Some(ms) = s.duration_ms {
                        let d = Duration::from_millis(ms);
                        Some(
                            theme
                                .duration
                                .apply_to(crate::ui::format_duration(d))
                                .to_string(),
                        )
                    } else {
                        s.last_run
                            .map(|ts| theme.dim.apply_to(format_relative_time(ts)).to_string())
                    }
                })
                .unwrap_or_default();

            ui.message(&format!(
                "    {} {:<20} {}",
                kind.styled(&theme),
                step_name,
                right_side,
            ));
        }

        // Show requirements section
        let all_reqs: HashSet<String> = config
            .steps
            .values()
            .flat_map(|s| s.requires.iter().cloned())
            .collect();

        if !all_reqs.is_empty() {
            ui.message("");
            ui.message(&format!("  {}", theme.key.apply_to("Requirements:")));

            let probe = EnvironmentProbe::run();
            let req_registry = RequirementRegistry::new().with_custom(&config.requirements);
            let mut gap_checker = GapChecker::new(&req_registry, &probe, &self.project_root);

            let mut sorted_reqs: Vec<&str> = all_reqs.iter().map(|s| s.as_str()).collect();
            sorted_reqs.sort();

            for req_name in sorted_reqs {
                let status = gap_checker.check_one(req_name);
                let (icon, desc) = format_requirement_status(&theme, &status);
                ui.message(&format!("    {} {:<20} {}", icon, req_name, desc));
            }
        }

        // Show recommendations
        let never_run: Vec<_> = config
            .steps
            .keys()
            .filter(|s| {
                state
                    .get_step(s)
                    .map(|st| st.status == StepStatus::NeverRun)
                    .unwrap_or(true)
            })
            .cloned()
            .collect();

        let failed: Vec<_> = config
            .steps
            .keys()
            .filter(|s| {
                state
                    .get_step(s)
                    .map(|st| st.status == StepStatus::Failed)
                    .unwrap_or(false)
            })
            .cloned()
            .collect();

        if !failed.is_empty() {
            ui.message("");
            ui.show_hint(&hints::after_failed_run(&failed));
        } else if !never_run.is_empty() {
            ui.message("");
            if never_run.len() == config.steps.len() {
                ui.show_hint(hints::all_steps_pending());
            } else {
                ui.show_hint(&hints::some_steps_pending(&never_run));
            }
        }

        Ok(CommandResult::success())
    }
}

/// Format a requirement status for display.
fn format_requirement_status(theme: &BivvyTheme, status: &RequirementStatus) -> (String, String) {
    match status {
        RequirementStatus::Satisfied => (
            theme.success.apply_to("✓").to_string(),
            theme.dim.apply_to("available").to_string(),
        ),
        RequirementStatus::SystemOnly { warning, .. } => (
            theme.warning.apply_to("⚠").to_string(),
            theme.warning.apply_to(warning).to_string(),
        ),
        RequirementStatus::Inactive {
            manager,
            activation_hint,
            ..
        } => (
            theme.warning.apply_to("⚠").to_string(),
            theme
                .warning
                .apply_to(format!("{} not activated ({})", manager, activation_hint))
                .to_string(),
        ),
        RequirementStatus::ServiceDown { start_hint, .. } => (
            theme.error.apply_to("✗").to_string(),
            theme.error.apply_to(start_hint).to_string(),
        ),
        RequirementStatus::Missing { install_hint, .. } => {
            let hint = install_hint.as_deref().unwrap_or("not installed");
            (
                theme.error.apply_to("✗").to_string(),
                theme.error.apply_to(hint).to_string(),
            )
        }
        RequirementStatus::Unknown => (
            theme.dim.apply_to("?").to_string(),
            theme.dim.apply_to("unknown requirement").to_string(),
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ui::MockUI;
    use std::fs;
    use tempfile::TempDir;

    fn setup_project(config: &str) -> TempDir {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), config).unwrap();
        temp
    }

    #[test]
    fn status_command_creation() {
        let temp = TempDir::new().unwrap();
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);

        assert_eq!(cmd.project_root(), temp.path());
    }

    #[test]
    fn status_no_config() {
        let temp = TempDir::new().unwrap();
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        assert!(!result.success);
        assert_eq!(result.exit_code, 2);
    }

    #[test]
    fn status_with_config() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        let result = cmd.execute(&mut ui).unwrap();

        assert!(result.success);
    }

    #[test]
    fn status_applies_config_default_output() {
        let config = r#"
app_name: Test
settings:
  default_output: quiet
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        assert_eq!(ui.output_mode(), crate::ui::OutputMode::Quiet);
    }

    #[test]
    fn status_shows_pending_for_never_run_steps() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // Never-run steps should show ◌ icon (pending)
        assert!(ui
            .messages()
            .iter()
            .any(|m| m.contains("◌") && m.contains("hello")));
        // Should NOT use warning for pending steps
        assert!(!ui.warnings().iter().any(|m| m.contains("hello")));
    }

    #[test]
    fn status_shows_header_with_app_name() {
        let config = r#"
app_name: MyApp
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // Should show app name in header
        assert!(ui.messages().iter().any(|m| m.contains("MyApp")));
        // Should show ⛺ tent icon
        assert!(ui.messages().iter().any(|m| m.contains("⛺")));
        // Should show "Status" label
        assert!(ui.messages().iter().any(|m| m.contains("Status")));
    }

    #[test]
    fn status_shows_hint_for_all_pending() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
  world:
    command: echo world
workflows:
  default:
    steps: [hello, world]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // All steps pending → hint to run setup
        assert!(ui.hints().iter().any(|m| m.contains("bivvy run")));
    }

    #[test]
    fn status_shows_steps_label() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        assert!(ui.messages().iter().any(|m| m.contains("Steps:")));
    }

    #[test]
    fn status_shows_requirements_section_when_requires_present() {
        let config = r#"
app_name: Test
steps:
  install_deps:
    command: bundle install
    requires:
      - ruby
workflows:
  default:
    steps: [install_deps]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // Should show Requirements label
        assert!(ui.messages().iter().any(|m| m.contains("Requirements:")));
        // Should show ruby requirement with some status
        assert!(ui.messages().iter().any(|m| m.contains("ruby")));
    }

    #[test]
    fn status_no_requirements_section_when_no_requires() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // Should NOT show Requirements label
        assert!(!ui.messages().iter().any(|m| m.contains("Requirements:")));
    }

    #[test]
    fn status_requirements_deduplicates() {
        let config = r#"
app_name: Test
steps:
  step_a:
    command: echo a
    requires:
      - node
  step_b:
    command: echo b
    requires:
      - node
workflows:
  default:
    steps: [step_a, step_b]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // "node" should appear only once in the requirements section
        let node_count = ui
            .messages()
            .iter()
            .filter(|m| m.contains("node") && !m.contains("Steps:") && !m.contains("⛺"))
            .count();
        assert_eq!(node_count, 1, "node should appear exactly once");
    }

    #[test]
    fn status_shows_environment_info() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs::default();
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // Should show Environment label
        assert!(ui.messages().iter().any(|m| m.contains("Environment:")));
        // The resolved name depends on where the test runs:
        // "ci" in CI (auto-detected), "development" locally (fallback)
        let has_env_name = ui
            .messages()
            .iter()
            .any(|m| m.contains("development") || m.contains("ci"));
        assert!(has_env_name, "Should show resolved environment name");
    }

    #[test]
    fn status_shows_environment_from_env_flag() {
        let config = r#"
app_name: Test
steps:
  hello:
    command: echo hello
workflows:
  default:
    steps: [hello]
"#;
        let temp = setup_project(config);
        let args = StatusArgs {
            env: Some("staging".to_string()),
            ..Default::default()
        };
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        assert!(ui.messages().iter().any(|m| m.contains("staging")));
    }

    #[test]
    fn format_requirement_status_satisfied() {
        let theme = BivvyTheme::new();
        let (icon, desc) = format_requirement_status(&theme, &RequirementStatus::Satisfied);
        assert!(icon.contains("✓"));
        assert!(desc.contains("available"));
    }

    #[test]
    fn format_requirement_status_missing() {
        let theme = BivvyTheme::new();
        let status = RequirementStatus::Missing {
            install_template: None,
            install_hint: Some("Install via mise".to_string()),
        };
        let (icon, desc) = format_requirement_status(&theme, &status);
        assert!(icon.contains("✗"));
        assert!(desc.contains("Install via mise"));
    }

    #[test]
    fn format_requirement_status_unknown() {
        let theme = BivvyTheme::new();
        let (icon, desc) = format_requirement_status(&theme, &RequirementStatus::Unknown);
        assert!(icon.contains("?"));
        assert!(desc.contains("unknown requirement"));
    }

    #[test]
    fn status_shows_skipped_steps_for_environment() {
        let config = r#"
app_name: Test
steps:
  dev_only:
    command: echo dev
    only_environments:
      - development
  always_run:
    command: echo always
workflows:
  default:
    steps: [dev_only, always_run]
"#;
        let temp = setup_project(config);
        let args = StatusArgs {
            env: Some("ci".to_string()),
            ..Default::default()
        };
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // dev_only should show as skipped in ci
        assert!(
            ui.messages()
                .iter()
                .any(|m| m.contains("dev_only") && m.contains("skipped in ci")),
            "Expected 'dev_only' to be shown as 'skipped in ci', messages: {:?}",
            ui.messages()
        );
        // always_run should show normally (no only_environments = runs in all)
        assert!(
            ui.messages()
                .iter()
                .any(|m| m.contains("always_run") && !m.contains("skipped")),
            "Expected 'always_run' to show without skipped, messages: {:?}",
            ui.messages()
        );
    }

    #[test]
    fn status_no_skipped_when_environment_matches() {
        let config = r#"
app_name: Test
steps:
  ci_step:
    command: echo ci
    only_environments:
      - ci
workflows:
  default:
    steps: [ci_step]
"#;
        let temp = setup_project(config);
        let args = StatusArgs {
            env: Some("ci".to_string()),
            ..Default::default()
        };
        let cmd = StatusCommand::new(temp.path(), args);
        let mut ui = MockUI::new();

        cmd.execute(&mut ui).unwrap();

        // ci_step should show normally (pending icon), not skipped
        assert!(
            ui.messages()
                .iter()
                .any(|m| m.contains("ci_step") && m.contains("◌")),
            "Expected 'ci_step' to show as pending, messages: {:?}",
            ui.messages()
        );
        assert!(
            !ui.messages()
                .iter()
                .any(|m| m.contains("ci_step") && m.contains("skipped")),
            "Expected 'ci_step' NOT to be skipped, messages: {:?}",
            ui.messages()
        );
    }
}

//! Configuration schema definitions for Bivvy.
//!
//! This module contains all the struct definitions that map to
//! the YAML configuration file format.

use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::path::PathBuf;

/// Root configuration structure for bivvy.yml
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct BivvyConfig {
    /// Application name (for display purposes)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub app_name: Option<String>,

    /// Global settings
    pub settings: Settings,

    /// Remote template sources
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub template_sources: Vec<TemplateSource>,

    /// Step definitions
    #[serde(default)]
    pub steps: HashMap<String, StepConfig>,

    /// Workflow definitions
    #[serde(default)]
    pub workflows: HashMap<String, WorkflowConfig>,

    /// Secrets configuration
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub secrets: HashMap<String, SecretConfig>,

    /// Config inheritance
    #[serde(skip_serializing_if = "Option::is_none")]
    pub extends: Option<Vec<ExtendsConfig>>,

    /// Custom requirement definitions
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub requirements: HashMap<String, CustomRequirement>,

    /// User-defined variables for interpolation.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub vars: HashMap<String, VarDefinition>,
}

/// Global settings that apply to all workflows and steps
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(default)]
pub struct Settings {
    /// Default output mode: verbose, quiet, silent
    #[serde(default = "default_output")]
    pub default_output: OutputMode,

    /// Enable logging to file
    #[serde(default, skip_serializing_if = "is_false")]
    pub logging: bool,

    /// Log file path (relative to project root)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub log_path: Option<PathBuf>,

    /// Global environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Global env file to load
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,

    /// Additional secret patterns to mask
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub secret_env: Vec<String>,

    /// Enable parallel execution
    #[serde(default, skip_serializing_if = "is_false")]
    pub parallel: bool,

    /// Maximum concurrent steps
    #[serde(
        default = "default_max_parallel",
        skip_serializing_if = "is_default_max_parallel"
    )]
    pub max_parallel: usize,

    /// History retention count
    #[serde(
        default = "default_history_retention",
        skip_serializing_if = "is_default_history_retention"
    )]
    pub history_retention: usize,

    /// Default environment name (used when no --env flag and no auto-detection)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_environment: Option<String>,

    /// Named environment configurations
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub environments: HashMap<String, EnvironmentConfig>,
}

impl Default for Settings {
    fn default() -> Self {
        Self {
            default_output: default_output(),
            logging: false,
            log_path: None,
            env: HashMap::new(),
            env_file: None,
            secret_env: Vec::new(),
            parallel: false,
            max_parallel: default_max_parallel(),
            history_retention: default_history_retention(),
            default_environment: None,
            environments: HashMap::new(),
        }
    }
}

fn default_output() -> OutputMode {
    OutputMode::Verbose
}

fn default_max_parallel() -> usize {
    4
}

fn is_default_max_parallel(v: &usize) -> bool {
    *v == default_max_parallel()
}

fn default_history_retention() -> usize {
    50
}

fn is_default_history_retention(v: &usize) -> bool {
    *v == default_history_retention()
}

fn is_false(v: &bool) -> bool {
    !v
}

fn is_true(v: &bool) -> bool {
    *v
}

fn is_zero(v: &u32) -> bool {
    *v == 0
}

/// Output verbosity mode
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum OutputMode {
    #[default]
    Verbose,
    Quiet,
    Silent,
}

/// Configuration for a single setup step
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct StepConfig {
    /// Reference to a template (mutually exclusive with inline config)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub template: Option<String>,

    /// Template inputs (when using template)
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub inputs: HashMap<String, serde_yaml::Value>,

    /// Step title (for display)
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,

    /// Step description
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Shell command to execute
    #[serde(skip_serializing_if = "Option::is_none")]
    pub command: Option<String>,

    /// Steps that must complete before this one
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub depends_on: Vec<String>,

    /// Check if step is already complete
    #[serde(skip_serializing_if = "Option::is_none")]
    pub completed_check: Option<CompletedCheck>,

    /// Precondition that must pass before the step runs.
    /// Unlike `completed_check` (which skips when passing), a precondition
    /// *fails* the step when it does not pass. `--force` does not bypass preconditions.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub precondition: Option<CompletedCheck>,

    /// Whether user can skip this step
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub skippable: bool,

    /// Step must run, cannot be skipped
    #[serde(default, skip_serializing_if = "is_false")]
    pub required: bool,

    /// Ask before re-running completed steps
    #[serde(default = "default_true", skip_serializing_if = "is_true")]
    pub prompt_if_complete: bool,

    /// Continue workflow if this step fails
    #[serde(default, skip_serializing_if = "is_false")]
    pub allow_failure: bool,

    /// Number of retries on failure
    #[serde(default, skip_serializing_if = "is_zero")]
    pub retry: u32,

    /// Step-specific environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Env file to load for this step
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,

    /// Don't fail if env_file is missing
    #[serde(default, skip_serializing_if = "is_false")]
    pub env_file_optional: bool,

    /// Required environment variables (fail if missing)
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub required_env: Vec<String>,

    /// Files to watch for change detection
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub watches: Vec<String>,

    /// Interactive prompts within this step
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub prompts: Vec<PromptConfig>,

    /// Step output settings
    #[serde(skip_serializing_if = "Option::is_none")]
    pub output: Option<StepOutputConfig>,

    /// Mark step as handling sensitive data
    #[serde(default, skip_serializing_if = "is_false")]
    pub sensitive: bool,

    /// Step requires sudo/elevated permissions
    #[serde(default, skip_serializing_if = "is_false")]
    pub requires_sudo: bool,

    /// Commands to run before the step
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub before: Vec<String>,

    /// Commands to run after the step succeeds
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub after: Vec<String>,

    /// System-level prerequisites this step requires (e.g., ruby, node, postgres-server).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub requires: Vec<String>,

    /// Per-environment overrides for this step.
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub environments: HashMap<String, StepEnvironmentOverride>,

    /// Restrict this step to specific environments.
    /// Empty list (default) means "run in all environments".
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub only_environments: Vec<String>,
}

fn default_true() -> bool {
    true
}

/// Check to determine if a step has already been completed.
///
/// This enables idempotent step execution by detecting when work
/// has already been done.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum CompletedCheck {
    /// Check if a file or directory exists
    FileExists {
        /// Path to check (relative to project root)
        path: String,
    },

    /// Check if a command succeeds (exit code 0)
    CommandSucceeds {
        /// Command to run
        command: String,
    },

    /// Use Bivvy's internal marker system
    Marker,

    /// All checks must pass
    All {
        /// List of checks that must all pass
        checks: Vec<CompletedCheck>,
    },

    /// Any check passing is sufficient
    Any {
        /// List of checks where at least one must pass
        checks: Vec<CompletedCheck>,
    },
}

/// Prompt configuration for interactive input
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PromptConfig {
    /// Unique key for this prompt (used in interpolation)
    pub key: String,

    /// Question to display
    pub question: String,

    /// Prompt type: select, multiselect, confirm, input
    #[serde(rename = "type")]
    pub prompt_type: PromptType,

    /// Options for select/multiselect
    #[serde(default)]
    pub options: Vec<PromptOption>,

    /// Default value
    pub default: Option<serde_yaml::Value>,
}

/// Type of interactive prompt
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum PromptType {
    Select,
    Multiselect,
    Confirm,
    Input,
}

/// Option for select/multiselect prompts
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PromptOption {
    /// Display label
    pub label: String,
    /// Value to use when selected
    pub value: String,
}

/// Step-specific output configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct StepOutputConfig {
    /// Output mode for this step
    pub default: Option<OutputMode>,

    /// Enable logging for this step
    pub logging: Option<bool>,
}

/// Configuration for a named workflow
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct WorkflowConfig {
    /// Human-readable description
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Ordered list of step names to execute
    #[serde(default)]
    pub steps: Vec<String>,

    /// Step-specific overrides for this workflow
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub overrides: HashMap<String, StepOverride>,

    /// Workflow-level settings
    #[serde(skip_serializing_if = "Option::is_none")]
    pub settings: Option<WorkflowSettings>,

    /// Workflow-level environment variables
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, String>,

    /// Workflow-level env file
    #[serde(skip_serializing_if = "Option::is_none")]
    pub env_file: Option<PathBuf>,
}

/// Per-step overrides within a workflow
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct StepOverride {
    /// Skip prompts, just run
    #[serde(default, skip_serializing_if = "is_false")]
    pub skip_prompt: bool,

    /// Override required flag
    #[serde(skip_serializing_if = "Option::is_none")]
    pub required: Option<bool>,

    /// Override prompt_if_complete flag
    #[serde(skip_serializing_if = "Option::is_none")]
    pub prompt_if_complete: Option<bool>,
}

/// Workflow-level settings overrides
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct WorkflowSettings {
    /// Force non-interactive mode for this workflow
    #[serde(default, skip_serializing_if = "is_false")]
    pub non_interactive: bool,
}

/// Remote template source configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TemplateSource {
    /// URL to template repository or file
    pub url: String,

    /// Priority (lower = higher priority)
    #[serde(default = "default_priority")]
    pub priority: u32,

    /// Network timeout in seconds
    #[serde(default = "default_timeout")]
    pub timeout: u64,

    /// Cache configuration
    pub cache: Option<CacheConfig>,

    /// Authentication configuration
    pub auth: Option<AuthConfig>,
}

fn default_priority() -> u32 {
    100
}

fn default_timeout() -> u64 {
    30
}

/// Cache configuration for remote templates
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CacheConfig {
    /// Time-to-live (e.g., "7d", "24h")
    pub ttl: String,

    /// Cache strategy: etag, git
    #[serde(default)]
    pub strategy: CacheStrategy,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum CacheStrategy {
    #[default]
    Etag,
    Git,
}

/// Authentication for remote template sources
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuthConfig {
    /// Auth type: bearer, header
    #[serde(rename = "type")]
    pub auth_type: AuthType,

    /// Environment variable containing the token
    pub token_env: String,

    /// Custom header name (for header auth type)
    pub header: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum AuthType {
    Bearer,
    Header,
}

/// Config inheritance source
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExtendsConfig {
    /// URL to base config
    pub url: String,
}

/// Secret configuration
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SecretConfig {
    /// Command to fetch the secret
    pub command: String,
}

/// A variable definition: either a static value or a shell-computed value.
///
/// In YAML, static values are plain strings and computed values use
/// `{ command: "..." }` syntax:
///
/// ```yaml
/// vars:
///   app_name: "bivvy"                       # static
///   version:
///     command: "cat VERSION"                 # computed
/// ```
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum VarDefinition {
    /// Computed from a shell command's stdout (trimmed).
    Computed {
        /// Shell command to run
        command: String,
    },
    /// A static string value.
    Static(String),
}

/// A project-specific requirement definition.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CustomRequirement {
    /// How to check if this requirement is satisfied
    pub check: CustomRequirementCheck,

    /// Template to use for installation
    #[serde(skip_serializing_if = "Option::is_none")]
    pub install_template: Option<String>,

    /// Human-readable install instructions
    #[serde(skip_serializing_if = "Option::is_none")]
    pub install_hint: Option<String>,
}

/// Check type for a custom requirement.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum CustomRequirementCheck {
    /// Check if a command succeeds (exit code 0)
    CommandSucceeds {
        /// Command to run
        command: String,
    },

    /// Check if a file or directory exists
    FileExists {
        /// Path to check
        path: String,
    },

    /// Check if a service is reachable
    ServiceReachable {
        /// Command to check reachability (e.g., curl health endpoint)
        command: String,
    },
}

/// Configuration for a named environment.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct EnvironmentConfig {
    /// Rules for auto-detecting this environment.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub detect: Vec<EnvironmentDetectRule>,

    /// Default workflow to run in this environment.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub default_workflow: Option<String>,

    /// Requirements that are assumed to be satisfied in this environment.
    /// These skip gap detection checks when this environment is active.
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub provided_requirements: Vec<String>,
}

/// A rule for auto-detecting an environment.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct EnvironmentDetectRule {
    /// Environment variable name to check.
    pub env: String,

    /// If set, the variable must equal this value. If absent, just checks presence.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub value: Option<String>,
}

/// Per-environment overrides for a step.
///
/// All fields are `Option` — only specified fields override the base step.
/// The `env` field uses `HashMap<String, Option<String>>`:
/// `Some(val)` = set/override, `None` = remove the key from the base env.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(default)]
pub struct StepEnvironmentOverride {
    /// Override step title
    #[serde(skip_serializing_if = "Option::is_none")]
    pub title: Option<String>,

    /// Override step description
    #[serde(skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,

    /// Override step command
    #[serde(skip_serializing_if = "Option::is_none")]
    pub command: Option<String>,

    /// Override/remove env vars (None value = remove key)
    #[serde(default, skip_serializing_if = "HashMap::is_empty")]
    pub env: HashMap<String, Option<String>>,

    /// Override completed check
    #[serde(skip_serializing_if = "Option::is_none")]
    pub completed_check: Option<CompletedCheck>,

    /// Override precondition
    #[serde(skip_serializing_if = "Option::is_none")]
    pub precondition: Option<CompletedCheck>,

    /// Override skippable
    #[serde(skip_serializing_if = "Option::is_none")]
    pub skippable: Option<bool>,

    /// Override allow_failure
    #[serde(skip_serializing_if = "Option::is_none")]
    pub allow_failure: Option<bool>,

    /// Override requires_sudo
    #[serde(skip_serializing_if = "Option::is_none")]
    pub requires_sudo: Option<bool>,

    /// Override sensitive
    #[serde(skip_serializing_if = "Option::is_none")]
    pub sensitive: Option<bool>,

    /// Override before hooks
    #[serde(skip_serializing_if = "Option::is_none")]
    pub before: Option<Vec<String>>,

    /// Override after hooks
    #[serde(skip_serializing_if = "Option::is_none")]
    pub after: Option<Vec<String>>,

    /// Override dependencies
    #[serde(skip_serializing_if = "Option::is_none")]
    pub depends_on: Option<Vec<String>>,

    /// Override requirements
    #[serde(skip_serializing_if = "Option::is_none")]
    pub requires: Option<Vec<String>>,

    /// Override watches
    #[serde(skip_serializing_if = "Option::is_none")]
    pub watches: Option<Vec<String>>,

    /// Override retry count
    #[serde(skip_serializing_if = "Option::is_none")]
    pub retry: Option<u32>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn empty_config_has_defaults() {
        let config: BivvyConfig = serde_yaml::from_str("").unwrap();
        assert_eq!(config.settings.default_output, OutputMode::Verbose);
        assert_eq!(config.settings.max_parallel, 4);
        assert_eq!(config.settings.history_retention, 50);
        assert!(config.steps.is_empty());
        assert!(config.workflows.is_empty());
    }

    #[test]
    fn parses_minimal_config() {
        let yaml = r#"
app_name: "MyApp"
settings:
  default_output: quiet
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.app_name, Some("MyApp".to_string()));
        assert_eq!(config.settings.default_output, OutputMode::Quiet);
    }

    #[test]
    fn parses_template_sources() {
        let yaml = r#"
template_sources:
  - url: "https://example.com/templates"
    priority: 10
    timeout: 60
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert_eq!(config.template_sources.len(), 1);
        assert_eq!(config.template_sources[0].priority, 10);
        assert_eq!(config.template_sources[0].timeout, 60);
    }

    #[test]
    fn parses_settings_with_env() {
        let yaml = r#"
settings:
  logging: true
  log_path: "logs/bivvy.log"
  env:
    RAILS_ENV: development
    DEBUG: "true"
  parallel: true
  max_parallel: 8
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.settings.logging);
        assert_eq!(
            config.settings.log_path,
            Some(PathBuf::from("logs/bivvy.log"))
        );
        assert_eq!(
            config.settings.env.get("RAILS_ENV"),
            Some(&"development".to_string())
        );
        assert!(config.settings.parallel);
        assert_eq!(config.settings.max_parallel, 8);
    }

    #[test]
    fn parses_extends_config() {
        let yaml = r#"
extends:
  - url: "https://example.com/base-config.yml"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.extends.is_some());
        assert_eq!(config.extends.as_ref().unwrap().len(), 1);
    }

    #[test]
    fn parses_secrets_config() {
        let yaml = r#"
secrets:
  db_password:
    command: "op read op://vault/database/password"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.secrets.contains_key("db_password"));
    }

    #[test]
    fn parses_step_with_template() {
        let yaml = r#"
steps:
  node_deps:
    template: yarn
    inputs:
      frozen: true
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["node_deps"];
        assert_eq!(step.template, Some("yarn".to_string()));
    }

    #[test]
    fn parses_step_with_inline_config() {
        let yaml = r#"
steps:
  custom:
    title: "Custom Step"
    command: "echo hello"
    depends_on: [other]
    env:
      MY_VAR: "value"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["custom"];
        assert_eq!(step.title, Some("Custom Step".to_string()));
        assert_eq!(step.command, Some("echo hello".to_string()));
        assert_eq!(step.depends_on, vec!["other"]);
    }

    #[test]
    fn step_defaults_are_correct() {
        let yaml = r#"
steps:
  minimal:
    command: "echo test"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["minimal"];
        assert!(step.skippable);
        assert!(!step.required);
        assert!(step.prompt_if_complete);
        assert!(!step.allow_failure);
        assert_eq!(step.retry, 0);
    }

    #[test]
    fn parses_step_with_prompts() {
        let yaml = r#"
steps:
  interactive:
    command: "yarn ${install_mode}"
    prompts:
      - key: install_mode
        question: "How to install?"
        type: select
        options:
          - label: "Normal"
            value: "install"
          - label: "Frozen"
            value: "install --frozen-lockfile"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["interactive"];
        assert_eq!(step.prompts.len(), 1);
        assert_eq!(step.prompts[0].key, "install_mode");
        assert_eq!(step.prompts[0].options.len(), 2);
    }

    #[test]
    fn parses_step_with_hooks() {
        let yaml = r#"
steps:
  database:
    command: "rails db:setup"
    before:
      - echo "Starting..."
    after:
      - echo "Done!"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        let step = &config.steps["database"];
        assert_eq!(step.before.len(), 1);
        assert_eq!(step.after.len(), 1);
    }

    #[test]
    fn step_config_defaults_to_empty_hooks() {
        let yaml = r#"
